INSERT INTO banks (id, name, description, category, version, question_count, questions_json, allowed_modes, enabled, created_at, updated_at) VALUES ('c-language-2026-code','C语言2026年题库全解通关代码','《程序设计技术基础》2026年题库全解通关代码 - 默写编程题','',1,63,'[{\"id\":1,\"type\":\"code\",\"category\":\"顺序结构程序练习\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：任意输入一个半径给r，求圆的面积。\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    double r, area;\\n    scanf(\\\"%lf\\\", &r);\\n    area = 3.1415926 * r * r;\\n    printf(\\\"面积:%.2f\\\\n\\\", area);\\n    return 0;\\n}\",\"explanation\":\"这是顺序结构程序练习的经典程序。记忆要点：定义双精度浮点数，公式为 3.1415926 * r * r。\",\"codeLanguage\":\"c\",\"memoryAid\":\"定义双精度浮点数，公式为 3.1415926 * r * r。\"},{\"id\":2,\"type\":\"code\",\"category\":\"顺序结构程序练习\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：从键盘输入一个浮点数，然后分别输出该数的整数部分和小数部分。\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    double num;\\n    scanf(\\\"%lf\\\", &num);\\n    int zheng = (int)num;\\n    double xiao = num - zheng;\\n    printf(\\\"整数:%d, 小数:%f\\\\n\\\", zheng, xiao);\\n    return 0;\\n}\",\"explanation\":\"这是顺序结构程序练习的经典程序。记忆要点：使用强转 (int) 截断获取整数，原数减去整数即得小数。\",\"codeLanguage\":\"c\",\"memoryAid\":\"使用强转 (int) 截断获取整数，原数减去整数即得小数。\"},{\"id\":3,\"type\":\"code\",\"category\":\"顺序结构程序练习\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：从键盘上输入小写字母，显示这个小写字母和大写字母以及对应的ASCII码。\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    char ch;\\n    scanf(\\\"%c\\\", &ch);\\n    printf(\\\"小写:%c(ASCII:%d)\\\\n\\\", ch, ch);\\n    printf(\\\"大写:%c(ASCII:%d)\\\\n\\\", ch - 32, ch - 32);\\n    return 0;\\n}\",\"explanation\":\"这是顺序结构程序练习的经典程序。记忆要点：大小写字母ASCII码相差32。\",\"codeLanguage\":\"c\",\"memoryAid\":\"大小写字母ASCII码相差32。\"},{\"id\":4,\"type\":\"code\",\"category\":\"顺序结构程序练习\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：输出以下图形（顺序结构直接打印）\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    printf(\\\"   *\\\\n\\\");\\n    printf(\\\"  ***\\\\n\\\");\\n    printf(\\\" *****\\\\n\\\");\\n    printf(\\\"*******\\\\n\\\");\\n    printf(\\\" *****\\\\n\\\");\\n    printf(\\\"  ***\\\\n\\\");\\n    printf(\\\"   *\\\\n\\\");\\n    return 0;\\n}\",\"explanation\":\"这是顺序结构程序练习的经典程序。记忆要点：考场直接用 printf 拼出菱形，最快最稳。\",\"codeLanguage\":\"c\",\"memoryAid\":\"考场直接用 printf 拼出菱形，最快最稳。\"},{\"id\":5,\"type\":\"code\",\"category\":\"顺序结构程序练习\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：任意输入一个5位的正整数，分别求出它每位上的数值，然后逆序输出（不限制位数版）。\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    int num;\\n    scanf(\\\"%d\\\", &num);\\n    while (num > 0) {\\n        printf(\\\"%d \\\", num % 10);\\n        num /= 10;\\n    }\\n    printf(\\\"\\\\n\\\");\\n    return 0;\\n}\",\"explanation\":\"这是顺序结构程序练习的经典程序。记忆要点：%10取尾数，/10剥除尾数，用 while 循环解决。\",\"codeLanguage\":\"c\",\"memoryAid\":\"%10取尾数，/10剥除尾数，用 while 循环解决。\"},{\"id\":6,\"type\":\"code\",\"category\":\"顺序结构程序练习\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：通过键盘上输入一位同学的5门课程的成绩，计算该同学的平均成绩和总成绩并输出。\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    double c1, c2, c3, c4, c5, sum, avg;\\n    scanf(\\\"%lf %lf %lf %lf %lf\\\", &c1, &c2, &c3, &c4, &c5);\\n    sum = c1 + c2 + c3 + c4 + c5;\\n    avg = sum / 5.0;\\n    printf(\\\"总分:%.2f, 平均分:%.2f\\\\n\\\", sum, avg);\\n    return 0;\\n}\",\"explanation\":\"这是顺序结构程序练习的经典程序。\",\"codeLanguage\":\"c\",\"memoryAid\":\"\"},{\"id\":7,\"type\":\"code\",\"category\":\"顺序结构程序练习\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：任意输入一个三角形的三边的值分别给a、b、c，求得并输出该三角形的面积。\",\"options\":[],\"answer\":\"#include <stdio.h>\\n#include <math.h>\\nint main() {\\n    double a, b, c, s, area;\\n    scanf(\\\"%lf %lf %lf\\\", &a, &b, &c);\\n    s = (a + b + c) / 2.0;\\n    area = sqrt(s * (s - a) * (s - b) * (s - c));\\n    printf(\\\"面积:%.2f\\\\n\\\", area);\\n    return 0;\\n}\",\"explanation\":\"这是顺序结构程序练习的经典程序。记忆要点：海伦公式 s = (a+b+c)/2, area = sqrt(s*(s-a)*(s-b)*(s-c))。\",\"codeLanguage\":\"c\",\"memoryAid\":\"海伦公式 s = (a+b+c)/2, area = sqrt(s*(s-a)*(s-b)*(s-c))。\"},{\"id\":8,\"type\":\"code\",\"category\":\"顺序结构程序练习\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：任意输入2个数值给自变量x和y，要求实现2个变量之间的数值交换（不能使用交换的思想/第三方变量）。\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    double x, y;\\n    scanf(\\\"%lf %lf\\\", &x, &y);\\n    x = x + y;\\n    y = x - y;\\n    x = x - y;\\n    printf(\\\"交换后: x=%.2f, y=%.2f\\\\n\\\", x, y);\\n    return 0;\\n}\",\"explanation\":\"这是顺序结构程序练习的经典程序。记忆要点：利用加减法做差值的逆向代换。\",\"codeLanguage\":\"c\",\"memoryAid\":\"利用加减法做差值的逆向代换。\"},{\"id\":9,\"type\":\"code\",\"category\":\"顺序结构程序练习\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：输入一个字母（假设是大写字母），将其替换为字母表中后移3位的字母（凯撒加密，如果超过Z则绕回A）。\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    char ch;\\n    scanf(\\\"%c\\\", &ch);\\n    if (ch >= \'A\' && ch <= \'Z\') {\\n        ch = (ch - \'A\' + 3) % 26 + \'A\';\\n    }\\n    printf(\\\"加密后:%c\\\\n\\\", ch);\\n    return 0;\\n}\",\"explanation\":\"这是顺序结构程序练习的经典程序。记忆要点：利用 % 26 实现循环回绕。\",\"codeLanguage\":\"c\",\"memoryAid\":\"利用 % 26 实现循环回绕。\"},{\"id\":10,\"type\":\"code\",\"category\":\"选择结构程序设计\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：任意输入一个正整数给x，判断其是奇数还是偶数？\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    int x;\\n    scanf(\\\"%d\\\", &x);\\n    if (x % 2 == 0) printf(\\\"偶数\\\\n\\\");\\n    else printf(\\\"奇数\\\\n\\\");\\n    return 0;\\n}\",\"explanation\":\"这是选择结构程序设计的经典程序。\",\"codeLanguage\":\"c\",\"memoryAid\":\"\"},{\"id\":11,\"type\":\"code\",\"category\":\"选择结构程序设计\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：任意输入一个年份，判断其实闰年还是平年？\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    int y;\\n    scanf(\\\"%d\\\", &y);\\n    if ((y % 4 == 0 && y % 100 != 0) || (y % 400 == 0)) {\\n        printf(\\\"闰年\\\\n\\\");\\n    } else {\\n        printf(\\\"平年\\\\n\\\");\\n    }\\n    return 0;\\n}\",\"explanation\":\"这是选择结构程序设计的经典程序。记忆要点：四年一闰百年不闰，或四百年一闰。\",\"codeLanguage\":\"c\",\"memoryAid\":\"四年一闰百年不闰，或四百年一闰。\"},{\"id\":12,\"type\":\"code\",\"category\":\"选择结构程序设计\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：任意输入3个数值分别给变量a、b、c，求得它们的最大值。\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    int a, b, c, max;\\n    scanf(\\\"%d %d %d\\\", &a, &b, &c);\\n    max = a;\\n    if (b > max) max = b;\\n    if (c > max) max = c;\\n    printf(\\\"最大值:%d\\\\n\\\", max);\\n    return 0;\\n}\",\"explanation\":\"这是选择结构程序设计的经典程序。\",\"codeLanguage\":\"c\",\"memoryAid\":\"\"},{\"id\":13,\"type\":\"code\",\"category\":\"选择结构程序设计\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：任意输入3个数值分别给变量a、b、c，要求按照从小到大的顺序输出。\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    int a, b, c, t;\\n    scanf(\\\"%d %d %d\\\", &a, &b, &c);\\n    if (a > b) { t = a; a = b; b = t; }\\n    if (a > c) { t = a; a = c; c = t; }\\n    if (b > c) { t = b; b = c; c = t; }\\n    printf(\\\"%d %d %d\\\\n\\\", a, b, c);\\n    return 0;\\n}\",\"explanation\":\"这是选择结构程序设计的经典程序。记忆要点：两两比较，三次代换，小的换到前面。\",\"codeLanguage\":\"c\",\"memoryAid\":\"两两比较，三次代换，小的换到前面。\"},{\"id\":14,\"type\":\"code\",\"category\":\"选择结构程序设计\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：任意输入a，b，c的值，求得并输出当y=0时，y=ax2+bx+c的解。\",\"options\":[],\"answer\":\"#include <stdio.h>\\n#include <math.h>\\nint main() {\\n    double a, b, c, disc, x1, x2;\\n    scanf(\\\"%lf %lf %lf\\\", &a, &b, &c);\\n    disc = b * b - 4 * a * c;\\n    if (disc >= 0) {\\n        x1 = (-b + sqrt(disc)) / (2 * a);\\n        x2 = (-b - sqrt(disc)) / (2 * a);\\n        printf(\\\"x1=%.2f, x2=%.2f\\\\n\\\", x1, x2);\\n    } else {\\n        printf(\\\"无实根\\\\n\\\");\\n    }\\n    return 0;\\n}\",\"explanation\":\"这是选择结构程序设计的经典程序。\",\"codeLanguage\":\"c\",\"memoryAid\":\"\"},{\"id\":15,\"type\":\"code\",\"category\":\"选择结构程序设计\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：任意输入一个正整数，判断其能被3、5整除的情况。\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    int n;\\n    scanf(\\\"%d\\\", &n);\\n    if (n % 3 == 0 && n % 5 == 0) printf(\\\"该数能同时被3和5整除\\\\n\\\");\\n    else if (n % 3 == 0 || n % 5 == 0) printf(\\\"该数能被其中一个数整除\\\\n\\\");\\n    else printf(\\\"该数既不能被3整除，也不能被5整除\\\\n\\\");\\n    return 0;\\n}\",\"explanation\":\"这是选择结构程序设计的经典程序。\",\"codeLanguage\":\"c\",\"memoryAid\":\"\"},{\"id\":16,\"type\":\"code\",\"category\":\"选择结构程序设计\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：将输入的大写字母转换为小写字母。\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    char ch;\\n    scanf(\\\"%c\\\", &ch);\\n    if (ch >= \'A\' && ch <= \'Z\') ch += 32;\\n    printf(\\\"%c\\\\n\\\", ch);\\n    return 0;\\n}\",\"explanation\":\"这是选择结构程序设计的经典程序。\",\"codeLanguage\":\"c\",\"memoryAid\":\"\"},{\"id\":17,\"type\":\"code\",\"category\":\"选择结构程序设计\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：任意输入一个年月日，计算并输出这天是该年的第几天？\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    int y, m, d, days = 0;\\n    int months[] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};\\n    scanf(\\\"%d %d %d\\\", &y, &m, &d);\\n    if ((y % 4 == 0 && y % 100 != 0) || (y % 400 == 0)) months[2] = 29;\\n    for (int i = 1; i < m; i++) days += months[i];\\n    days += d;\\n    printf(\\\"第%d天\\\\n\\\", days);\\n    return 0;\\n}\",\"explanation\":\"这是选择结构程序设计的经典程序。记忆要点：用静态数组查表累加，注意闰年修正。\",\"codeLanguage\":\"c\",\"memoryAid\":\"用静态数组查表累加，注意闰年修正。\"},{\"id\":18,\"type\":\"code\",\"category\":\"选择结构程序设计\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：任意输入某个同学的期末成绩，将其转换为对应的5级等级制成绩输出。\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    int s;\\n    scanf(\\\"%d\\\", &s);\\n    if (s < 0 || s > 100) return 0;\\n    switch (s / 10) {\\n        case 10:\\n        case 9:  printf(\\\"优\\\\n\\\"); break;\\n        case 8:  printf(\\\"良\\\\n\\\"); break;\\n        case 7:  printf(\\\"中\\\\n\\\"); break;\\n        case 6:  printf(\\\"及格\\\\n\\\"); break;\\n        default: printf(\\\"不及格\\\\n\\\"); break;\\n    }\\n    return 0;\\n}\",\"explanation\":\"这是选择结构程序设计的经典程序。记忆要点：利用 score / 10 将成绩归类，使用 switch-case。\",\"codeLanguage\":\"c\",\"memoryAid\":\"利用 score / 10 将成绩归类，使用 switch-case。\"},{\"id\":19,\"type\":\"code\",\"category\":\"选择结构程序设计\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：任意输入2个数值之间的四则运算表达式，输出结果（例如输入：10+20 输出30）。\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    double a, b;\\n    char op;\\n    if (scanf(\\\"%lf%c%lf\\\", &a, &op, &b) == 3) {\\n        switch (op) {\\n            case \'+\': printf(\\\"%.2f\\\\n\\\", a + b); break;\\n            case \'-\': printf(\\\"%.2f\\\\n\\\", a - b); break;\\n            case \'*\': printf(\\\"%.2f\\\\n\\\", a * b); break;\\n            case \'/\': printf(\\\"%.2f\\\\n\\\", a / b); break;\\n        }\\n    }\\n    return 0;\\n}\",\"explanation\":\"这是选择结构程序设计的经典程序。\",\"codeLanguage\":\"c\",\"memoryAid\":\"\"},{\"id\":20,\"type\":\"code\",\"category\":\"循环结构程序设计\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：求s=1+2+3+……+98+99+100\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    int s = 0;\\n    for (int i = 1; i <= 100; i++) s += i;\\n    printf(\\\"s = %d\\\\n\\\", s);\\n    return 0;\\n}\",\"explanation\":\"这是循环结构程序设计的经典程序。\",\"codeLanguage\":\"c\",\"memoryAid\":\"\"},{\"id\":21,\"type\":\"code\",\"category\":\"循环结构程序设计\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：求s=1+3+5+……+97+99\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    int s = 0;\\n    for (int i = 1; i <= 99; i += 2) s += i;\\n    printf(\\\"s = %d\\\\n\\\", s);\\n    return 0;\\n}\",\"explanation\":\"这是循环结构程序设计的经典程序。\",\"codeLanguage\":\"c\",\"memoryAid\":\"\"},{\"id\":22,\"type\":\"code\",\"category\":\"循环结构程序设计\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：求s=1-3+5-7+……+97-99\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    int s = 0, sign = 1;\\n    for (int i = 1; i <= 99; i += 2) {\\n        s += sign * i;\\n        sign = -sign;\\n    }\\n    printf(\\\"s = %d\\\\n\\\", s);\\n    return 0;\\n}\",\"explanation\":\"这是循环结构程序设计的经典程序。记忆要点：利用 sign = -sign 每次循环切换正负。\",\"codeLanguage\":\"c\",\"memoryAid\":\"利用 sign = -sign 每次循环切换正负。\"},{\"id\":23,\"type\":\"code\",\"category\":\"循环结构程序设计\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：求π的值，已知π/4≈1-1/3+1/5-1/7+……计算至某项的绝对值小于1E-6为止。\",\"options\":[],\"answer\":\"#include <stdio.h>\\n#include <math.h>\\nint main() {\\n    double sum = 0, term = 1.0, i = 1.0;\\n    int sign = 1;\\n    while (fabs(term) >= 1e-6) {\\n        sum += term;\\n        i += 2;\\n        sign = -sign;\\n        term = sign / i;\\n    }\\n    printf(\\\"pi = %f\\\\n\\\", sum * 4);\\n    return 0;\\n}\",\"explanation\":\"这是循环结构程序设计的经典程序。\",\"codeLanguage\":\"c\",\"memoryAid\":\"\"},{\"id\":24,\"type\":\"code\",\"category\":\"循环结构程序设计\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：已知s=1+11+111+1111+……，一直加到n位1，n的值自己输入。\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    int n, s = 0, t = 0;\\n    scanf(\\\"%d\\\", &n);\\n    for (int i = 1; i <= n; i++) {\\n        t = t * 10 + 1;\\n        s += t;\\n    }\\n    printf(\\\"s = %d\\\\n\\\", s);\\n    return 0;\\n}\",\"explanation\":\"这是循环结构程序设计的经典程序。记忆要点：当前项公式 t = t * 10 + 1。\",\"codeLanguage\":\"c\",\"memoryAid\":\"当前项公式 t = t * 10 + 1。\"},{\"id\":25,\"type\":\"code\",\"category\":\"循环结构程序设计\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：输入30名学生的程序设计成绩，计算并输出所有学生的平均分和最高成绩。\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    double score, sum = 0, max = 0;\\n    for (int i = 0; i < 30; i++) {\\n        scanf(\\\"%lf\\\", &score);\\n        sum += score;\\n        if (score > max) max = score;\\n    }\\n    printf(\\\"平均分:%.2f, 最高分:%.2f\\\\n\\\", sum / 30.0, max);\\n    return 0;\\n}\",\"explanation\":\"这是循环结构程序设计的经典程序。\",\"codeLanguage\":\"c\",\"memoryAid\":\"\"},{\"id\":26,\"type\":\"code\",\"category\":\"循环结构程序设计\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：输入一批整数，输入0时表示输入结束，求正整数的个数以及它们的和。\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    int n, count = 0, sum = 0;\\n    while (1) {\\n        scanf(\\\"%d\\\", &n);\\n        if (n == 0) break;\\n        if (n > 0) { count++; sum += n; }\\n    }\\n    printf(\\\"个数:%d, 和:%d\\\\n\\\", count, sum);\\n    return 0;\\n}\",\"explanation\":\"这是循环结构程序设计的经典程序。\",\"codeLanguage\":\"c\",\"memoryAid\":\"\"},{\"id\":27,\"type\":\"code\",\"category\":\"循环结构程序设计\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：任意输入2个正整数给自变量x和y，要求求得它们之间的最大公约数和最小公倍数。\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    int x, y, a, b, t;\\n    scanf(\\\"%d %d\\\", &x, &y);\\n    a = x; b = y;\\n    while (b != 0) { t = a % b; a = b; b = t; }\\n    printf(\\\"最大公约数:%d\\\\n\\\", a);\\n    printf(\\\"最小公倍数:%d\\\\n\\\", (x * y) / a);\\n    return 0;\\n}\",\"explanation\":\"这是循环结构程序设计的经典程序。记忆要点：必考辗转相除法。\",\"codeLanguage\":\"c\",\"memoryAid\":\"必考辗转相除法。\"},{\"id\":28,\"type\":\"code\",\"category\":\"循环结构程序设计\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：任意输入一个正整数，判断其是否是素数。\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    int n, is_prime = 1;\\n    scanf(\\\"%d\\\", &n);\\n    if (n < 2) is_prime = 0;\\n    for (int i = 2; i * i <= n; i++) {\\n        if (n % i == 0) { is_prime = 0; break; }\\n    }\\n    if (is_prime) printf(\\\"是素数\\\\n\\\");\\n    else printf(\\\"不是素数\\\\n\\\");\\n    return 0;\\n}\",\"explanation\":\"这是循环结构程序设计的经典程序。\",\"codeLanguage\":\"c\",\"memoryAid\":\"\"},{\"id\":29,\"type\":\"code\",\"category\":\"循环结构程序设计\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：打印出所有的“水仙花数”。\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    for (int i = 100; i <= 999; i++) {\\n        int a = i / 100, b = (i / 10) % 10, c = i % 10;\\n        if (a*a*a + b*b*b + c*c*c == i) printf(\\\"%d \\\", i);\\n    }\\n    printf(\\\"\\\\n\\\");\\n    return 0;\\n}\",\"explanation\":\"这是循环结构程序设计的经典程序。\",\"codeLanguage\":\"c\",\"memoryAid\":\"\"},{\"id\":30,\"type\":\"code\",\"category\":\"循环结构程序设计\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：从键盘上任意输入2个正整数给a and b，计算a and b之间所有整数（包括a and b）的累加和。\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    int a, b, sum = 0;\\n    scanf(\\\"%d %d\\\", &a, &b);\\n    int start = (a < b) ? a : b;\\n    int end = (a > b) ? a : b;\\n    for (int i = start; i <= end; i++) sum += i;\\n    printf(\\\"和:%d\\\\n\\\", sum);\\n    return 0;\\n}\",\"explanation\":\"这是循环结构程序设计的经典程序。\",\"codeLanguage\":\"c\",\"memoryAid\":\"\"},{\"id\":31,\"type\":\"code\",\"category\":\"循环结构程序设计\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：小猴摘桃问题（第7天早上剩1个，求总数）。\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    int count = 1;\\n    for (int i = 1; i <= 6; i++) count = (count + 1) * 2;\\n    printf(\\\"总数:%d\\\\n\\\", count);\\n    return 0;\\n}\",\"explanation\":\"这是循环结构程序设计的经典程序。记忆要点：倒推法，前一天 = (今天 + 1) * 2。\",\"codeLanguage\":\"c\",\"memoryAid\":\"倒推法，前一天 = (今天 + 1) * 2。\"},{\"id\":32,\"type\":\"code\",\"category\":\"循环结构程序设计\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：求s=1+2！+3！+4！+……+19！+20！\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    double sum = 0, term = 1;\\n    for (int i = 1; i <= 20; i++) { term *= i; sum += term; }\\n    printf(\\\"s = %.0f\\\\n\\\", sum);\\n    return 0;\\n}\",\"explanation\":\"这是循环结构程序设计的经典程序。记忆要点：单层循环，累乘即得当前项。注意大数用 double。\",\"codeLanguage\":\"c\",\"memoryAid\":\"单层循环，累乘即得当前项。注意大数用 double。\"},{\"id\":33,\"type\":\"code\",\"category\":\"循环结构程序设计\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：编写程序输出9*9乘法表。\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    for (int i = 1; i <= 9; i++) {\\n        for (int j = 1; j <= i; j++) printf(\\\"%d*%d=%-2d \\\", j, i, i * j);\\n        printf(\\\"\\\\n\\\");\\n    }\\n    return 0;\\n}\",\"explanation\":\"这是循环结构程序设计的经典程序。\",\"codeLanguage\":\"c\",\"memoryAid\":\"\"},{\"id\":34,\"type\":\"code\",\"category\":\"循环结构程序设计\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：用循环的思想打印星号菱形图形。\",\"options\":[],\"answer\":\"#include <stdio.h>\\n#include <stdlib.h>\\nint main() {\\n    for (int i = -3; i <= 3; i++) {\\n        int spaces = abs(i), stars = 7 - 2 * spaces;\\n        for (int j = 0; j < spaces; j++) printf(\\\" \\\");\\n        for (int j = 0; j < stars; j++) printf(\\\"*\\\");\\n        printf(\\\"\\\\n\\\");\\n    }\\n    return 0;\\n}\",\"explanation\":\"这是循环结构程序设计的经典程序。记忆要点：坐标轴绝对值对称法，绝对精简高端。\",\"codeLanguage\":\"c\",\"memoryAid\":\"坐标轴绝对值对称法，绝对精简高端。\"},{\"id\":35,\"type\":\"code\",\"category\":\"循环结构程序设计\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：输出1000以内所有的质数。\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    for (int i = 2; i <= 1000; i++) {\\n        int is_prime = 1;\\n        for (int j = 2; j * j <= i; j++) {\\n            if (i % j == 0) { is_prime = 0; break; }\\n        }\\n        if (is_prime) printf(\\\"%d \\\", i);\\n    }\\n    printf(\\\"\\\\n\\\");\\n    return 0;\\n}\",\"explanation\":\"这是循环结构程序设计的经典程序。\",\"codeLanguage\":\"c\",\"memoryAid\":\"\"},{\"id\":36,\"type\":\"code\",\"category\":\"循环结构程序设计\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：输入1000以内所有的完数。\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    for (int i = 1; i <= 1000; i++) {\\n        int sum = 0;\\n        for (int j = 1; j < i; j++) if (i % j == 0) sum += j;\\n        if (sum == i) printf(\\\"%d \\\", i);\\n    }\\n    printf(\\\"\\\\n\\\");\\n    return 0;\\n}\",\"explanation\":\"这是循环结构程序设计的经典程序。\",\"codeLanguage\":\"c\",\"memoryAid\":\"\"},{\"id\":37,\"type\":\"code\",\"category\":\"循环结构程序设计\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：红球3白球5黑球6任取8个至少一白，输出组合并计算概率。\",\"options\":[],\"answer\":\"#include <stdio.h>\\nlong comb(int n, int m) {\\n    if (m < 0 || m > n) return 0;\\n    long res = 1;\\n    for (int i = 1; i <= m; i++) res = res * (n - i + 1) / i;\\n    return res;\\n}\\nint main() {\\n    long valid_ways = 0;\\n    for (int r = 0; r <= 3; r++) {\\n        for (int w = 1; w <= 5; w++) {\\n            for (int b = 0; b <= 6; b++) {\\n                if (r + w + b == 8) {\\n                    printf(\\\"红:%d, 白:%d, 黑:%d\\\\n\\\", r, w, b);\\n                    valid_ways += comb(3, r) * comb(5, w) * comb(6, b);\\n                }\\n            }\\n        }\\n    }\\n    printf(\\\"概率为: %f\\\\n\\\", (double)valid_ways / comb(14, 8));\\n    return 0;\\n}\",\"explanation\":\"这是循环结构程序设计的经典程序。记忆要点：至少一白即 w 从 1 开始，总事件组合数为 C(14, 8) = 3003。\",\"codeLanguage\":\"c\",\"memoryAid\":\"至少一白即 w 从 1 开始，总事件组合数为 C(14, 8) = 3003。\"},{\"id\":38,\"type\":\"code\",\"category\":\"循环结构程序设计\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：有若干只鸡兔同在一个笼子里，有36个头，100只脚，问各有多少只鸡和兔？\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    for (int j = 0; j <= 36; j++) {\\n        int t = 36 - j;\\n        if (j * 2 + t * 4 == 100) printf(\\\"鸡:%d, 兔:%d\\\\n\\\", j, t);\\n    }\\n    return 0;\\n}\",\"explanation\":\"这是循环结构程序设计的经典程序。\",\"codeLanguage\":\"c\",\"memoryAid\":\"\"},{\"id\":39,\"type\":\"code\",\"category\":\"循环结构程序设计\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：0-9可以组成多少个没有重复的3位偶数。\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    int count = 0;\\n    for (int a = 1; a <= 9; a++) {\\n        for (int b = 0; b <= 9; b++) {\\n            for (int c = 0; c <= 8; c += 2) {\\n                if (a != b && b != c && a != c) count++;\\n            }\\n        }\\n    }\\n    printf(\\\"方案数:%d\\\\n\\\", count);\\n    return 0;\\n}\",\"explanation\":\"这是循环结构程序设计的经典程序。\",\"codeLanguage\":\"c\",\"memoryAid\":\"\"},{\"id\":40,\"type\":\"code\",\"category\":\"循环结构程序设计\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：求出用1元人民币兑换1分，2分，5分硬币的所有兑换方案，要求硬币总数是70枚。\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    for (int a = 0; a <= 70; a++) {\\n        for (int b = 0; b <= 50; b++) {\\n            int c = 70 - a - b;\\n            if (c >= 0 && a * 1 + b * 2 + c * 5 == 100) {\\n                printf(\\\"1分:%d, 2分:%d, 5分:%d\\\\n\\\", a, b, c);\\n            }\\n        }\\n    }\\n    return 0;\\n}\",\"explanation\":\"这是循环结构程序设计的经典程序。\",\"codeLanguage\":\"c\",\"memoryAid\":\"\"},{\"id\":41,\"type\":\"code\",\"category\":\"循环结构程序设计\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：任意输入x的值，求 sinx 的近似值直到绝对值小于 1E-6。\",\"options\":[],\"answer\":\"#include <stdio.h>\\n#include <math.h>\\nint main() {\\n    double x, sum, term;\\n    scanf(\\\"%lf\\\", &x);\\n    sum = 0; term = x; int i = 1;\\n    while (fabs(term) >= 1e-6) {\\n        sum += term;\\n        i += 2;\\n        term = -term * x * x / ((i - 1) * i);\\n    }\\n    printf(\\\"sinx ≈ %f\\\\n\\\", sum);\\n    return 0;\\n}\",\"explanation\":\"这是循环结构程序设计的经典程序。\",\"codeLanguage\":\"c\",\"memoryAid\":\"\"},{\"id\":42,\"type\":\"code\",\"category\":\"循环结构程序设计\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：百鸡问题（母鸡3元, 公鸡2元, 小鸡0.5元，100元买100只鸡）。\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    for (int m = 0; m <= 33; m++) {\\n        for (int g = 0; g <= 50; g++) {\\n            int x = 100 - m - g;\\n            if (x >= 0 && m * 3.0 + g * 2.0 + x * 0.5 == 100.0) {\\n                printf(\\\"母鸡:%d, 公鸡:%d, 小鸡:%d\\\\n\\\", m, g, x);\\n            }\\n        }\\n    }\\n    return 0;\\n}\",\"explanation\":\"这是循环结构程序设计的经典程序。\",\"codeLanguage\":\"c\",\"memoryAid\":\"\"},{\"id\":43,\"type\":\"code\",\"category\":\"循环结构程序设计\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：高校排考方案（周一到周五排3门，高数最早，计算机不在周四）。\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    int count = 0;\\n    for (int m = 1; m <= 5; m++) {\\n        for (int c = 1; c <= 5; c++) {\\n            for (int e = 1; e <= 5; e++) {\\n                if (m != c && c != e && m != e) {\\n                    if (m < c && m < e && c != 4) {\\n                        count++;\\n                        printf(\\\"高数:周%d, 计算机:周%d, 英语:周%d\\\\n\\\", m, c, e);\\n                    }\\n                }\\n            }\\n        }\\n    }\\n    printf(\\\"总排考方案数:%d\\\\n\\\", count);\\n    return 0;\\n}\",\"explanation\":\"这是循环结构程序设计的经典程序。\",\"codeLanguage\":\"c\",\"memoryAid\":\"\"},{\"id\":44,\"type\":\"code\",\"category\":\"循环结构程序设计\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：某君每次吹熄与年龄相同根数的蜡烛，一共吹熄了236根，问从多少岁开始过生日。\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    for (int start = 1; start <= 100; start++) {\\n        int sum = 0;\\n        for (int age = start; age <= 100; age++) {\\n            sum += age;\\n            if (sum == 236) printf(\\\"从%d岁开始\\\\n\\\", start);\\n        }\\n    }\\n    return 0;\\n}\",\"explanation\":\"这是循环结构程序设计的经典程序。\",\"codeLanguage\":\"c\",\"memoryAid\":\"\"},{\"id\":45,\"type\":\"code\",\"category\":\"循环结构程序设计\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：海盗平分4瓶酒方程推断（1/a + 1/b + 1/c + 1/d == 1）。\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    for (int a = 4; a <= 20; a++) {\\n        for (int b = 3; b < a; b++) {\\n            for (int c = 2; c < b; c++) {\\n                for (int d = 1; d < c; d++) {\\n                    if (b*c*d + a*c*d + a*b*d + a*b*c == a*b*c*d) {\\n                        printf(\\\"总共%d人, 依次剩:%d, %d, %d人\\\\n\\\", a, b, c, d);\\n                    }\\n                }\\n            }\\n        }\\n    }\\n    return 0;\\n}\",\"explanation\":\"这是循环结构程序设计的经典程序。记忆要点：由于全倒，通分化简为整型判断方程。\",\"codeLanguage\":\"c\",\"memoryAid\":\"由于全倒，通分化简为整型判断方程。\"},{\"id\":46,\"type\":\"code\",\"category\":\"数组\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：输入一个寝室6位同学的身高，要求按照从小到大的顺序输出。\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    double h[6], t;\\n    for (int i = 0; i < 6; i++) scanf(\\\"%lf\\\", &h[i]);\\n    for (int i = 0; i < 5; i++) {\\n        for (int j = 0; j < 5 - i; j++) {\\n            if (h[j] > h[j+1]) { t = h[j]; h[j] = h[j+1]; h[j+1] = t; }\\n        }\\n    }\\n    for (int i = 0; i < 6; i++) printf(\\\"%.2f \\\", h[i]);\\n    printf(\\\"\\\\n\\\");\\n    return 0;\\n}\",\"explanation\":\"这是数组的经典程序。记忆要点：极高频经典冒泡排序。\",\"codeLanguage\":\"c\",\"memoryAid\":\"极高频经典冒泡排序。\"},{\"id\":47,\"type\":\"code\",\"category\":\"数组\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：输入某班级所有同学的程序设计技术期末成绩（33人），要求输出最好的2位同学的成绩。\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    double score, max1 = -1, max2 = -1;\\n    for (int i = 0; i < 33; i++) {\\n        scanf(\\\"%lf\\\", &score);\\n        if (score > max1) { max2 = max1; max1 = score; }\\n        else if (score > max2) { max2 = score; }\\n    }\\n    printf(\\\"第一名:%.2f, 第二名:%.2f\\\\n\\\", max1, max2);\\n    return 0;\\n}\",\"explanation\":\"这是数组的经典程序。\",\"codeLanguage\":\"c\",\"memoryAid\":\"\"},{\"id\":48,\"type\":\"code\",\"category\":\"数组\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：校园歌手大赛，一共有7位裁判打分，去掉一个最高分和最低分算平均分。\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    double score, sum = 0, max = -1, min = 101;\\n    for (int i = 0; i < 7; i++) {\\n        scanf(\\\"%lf\\\", &score);\\n        sum += score;\\n        if (score > max) max = score;\\n        if (score < min) min = score;\\n    }\\n    printf(\\\"最后得分:%.2f\\\\n\\\", (sum - max - min) / 5.0);\\n    return 0;\\n}\",\"explanation\":\"这是数组的经典程序。\",\"codeLanguage\":\"c\",\"memoryAid\":\"\"},{\"id\":49,\"type\":\"code\",\"category\":\"数组\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：在数组中存储10个同学C语言的成绩，计算平均成绩，并输出与平均值最接近的数。\",\"options\":[],\"answer\":\"#include <stdio.h>\\n#include <math.h>\\nint main() {\\n    double a[10], sum = 0, avg, ans, min_diff;\\n    for (int i = 0; i < 10; i++) { scanf(\\\"%lf\\\", &a[i]); sum += a[i]; }\\n    avg = sum / 10.0; min_diff = fabs(a[0] - avg); ans = a[0];\\n    for (int i = 1; i < 10; i++) {\\n        if (fabs(a[i] - avg) < min_diff) { min_diff = fabs(a[i] - avg); ans = a[i]; }\\n    }\\n    printf(\\\"最接近的数:%.2f\\\\n\\\", ans);\\n    return 0;\\n}\",\"explanation\":\"这是数组的经典程序。\",\"codeLanguage\":\"c\",\"memoryAid\":\"\"},{\"id\":50,\"type\":\"code\",\"category\":\"数组\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：输入班级33位同学期末成绩，分别统计优，良，中，及格，不及格人数及百分比。\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    int score, counts[5] = {0};\\n    for (int i = 0; i < 33; i++) {\\n        scanf(\\\"%d\\\", &score);\\n        if (score >= 90) counts[0]++;\\n        else if (score >= 80) counts[1]++;\\n        else if (score >= 70) counts[2]++;\\n        else if (score >= 60) counts[3]++;\\n        else counts[4]++;\\n    }\\n    char *labels[] = {\\\"优\\\", \\\"良\\\", \\\"中\\\", \\\"及格\\\", \\\"不及格\\\"};\\n    for (int i = 0; i < 5; i++) {\\n        printf(\\\"%s: %d人, 占比:%.2f%%\\\\n\\\", labels[i], counts[i], (counts[i] / 33.0) * 100);\\n    }\\n    return 0;\\n}\",\"explanation\":\"这是数组的经典程序。\",\"codeLanguage\":\"c\",\"memoryAid\":\"\"},{\"id\":51,\"type\":\"code\",\"category\":\"数组\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：FIBONACCI 数列，请编程输出该数列的前20项。\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    int f[20] = {1, 1};\\n    printf(\\\"1\\\\n1\\\\n\\\");\\n    for (int i = 2; i < 20; i++) {\\n        f[i] = f[i-1] + f[i-2];\\n        printf(\\\"%d\\\\n\\\", f[i]);\\n    }\\n    return 0;\\n}\",\"explanation\":\"这是数组的经典程序。\",\"codeLanguage\":\"c\",\"memoryAid\":\"\"},{\"id\":52,\"type\":\"code\",\"category\":\"数组\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：给一个一维数组任意输入6个整数，要求建立一个循环右移方阵并输出。\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    int a[6];\\n    for (int i = 0; i < 6; i++) scanf(\\\"%d\\\", &a[i]);\\n    for (int i = 0; i < 6; i++) {\\n        for (int j = 0; j < 6; j++) printf(\\\"%d\\\\t\\\", a[(j - i + 6) % 6]);\\n        printf(\\\"\\\\n\\\");\\n    }\\n    return 0;\\n}\",\"explanation\":\"这是数组的经典程序。记忆要点：利用一维数组配合数学公式 (j - i + 6) % 6 映射，无需开二维数组。\",\"codeLanguage\":\"c\",\"memoryAid\":\"利用一维数组配合数学公式 (j - i + 6) % 6 映射，无需开二维数组。\"},{\"id\":53,\"type\":\"code\",\"category\":\"数组\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：医院想统计某项疾病患病与年龄的关系，按 0-18、19-35、36-60、61以上统计比例。\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    int n, age, c[4] = {0};\\n    scanf(\\\"%d\\\", &n);\\n    for (int i = 0; i < n; i++) {\\n        scanf(\\\"%d\\\", &age);\\n        if (age <= 18) c[0]++;\\n        else if (age <= 35) c[1]++;\\n        else if (age <= 60) c[2]++;\\n        else c[3]++;\\n    }\\n    for (int i = 0; i < 4; i++) printf(\\\"段%d比例:%.2f%%\\\\n\\\", i+1, (c[i]/(double)n)*100);\\n    return 0;\\n}\",\"explanation\":\"这是数组的经典程序。\",\"codeLanguage\":\"c\",\"memoryAid\":\"\"},{\"id\":54,\"type\":\"code\",\"category\":\"数组\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：任意输入一段英文，统计其中英文字符 a 的个数，不区分大小写。\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    char s[200]; int count = 0;\\n    gets(s);\\n    for (int i = 0; s[i] != \'\\\\0\'; i++) {\\n        if (s[i] == \'a\' || s[i] == \'A\') count++;\\n    }\\n    printf(\\\"count = %d\\\\n\\\", count);\\n    return 0;\\n}\",\"explanation\":\"这是数组的经典程序。\",\"codeLanguage\":\"c\",\"memoryAid\":\"\"},{\"id\":55,\"type\":\"code\",\"category\":\"数组\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：任意输入一段英文，分别统计出其中26个英文字母各自的个数，不区分大小写。\",\"options\":[],\"answer\":\"#include <stdio.h>\\n#include <ctype.h>\\nint main() {\\n    char s[200]; int count[26] = {0};\\n    gets(s);\\n    for (int i = 0; s[i] != \'\\\\0\'; i++) {\\n        if (isalpha(s[i])) count[tolower(s[i]) - \'a\']++;\\n    }\\n    for (int i = 0; i < 26; i++) {\\n        if (count[i] > 0) printf(\\\"%c: %d\\\\n\\\", \'a\' + i, count[i]);\\n    }\\n    return 0;\\n}\",\"explanation\":\"这是数组的经典程序。\",\"codeLanguage\":\"c\",\"memoryAid\":\"\"},{\"id\":56,\"type\":\"code\",\"category\":\"数组\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：任意输入一段英文，分别统计出英文字符、数字字符、空格字符和其他字符等四大类字符各自的个数。\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    char s[200]; int l=0, d=0, sp=0, o=0;\\n    gets(s);\\n    for (int i = 0; s[i] != \'\\\\0\'; i++) {\\n        if ((s[i]>=\'a\'&&s[i]<=\'z\')||(s[i]>=\'A\'&&s[i]<=\'Z\')) l++;\\n        else if (s[i]>=\'0\'&&s[i]<=\'9\') d++;\\n        else if (s[i]==\' \') sp++;\\n        else o++;\\n    }\\n    printf(\\\"字母:%d, 数字:%d, 空格:%d, 其他:%d\\\\n\\\", l, d, sp, o);\\n    return 0;\\n}\",\"explanation\":\"这是数组的经典程序。\",\"codeLanguage\":\"c\",\"memoryAid\":\"\"},{\"id\":57,\"type\":\"code\",\"category\":\"数组\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：任意输入一段英文，统计其中英文单词的个数。\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    char s[200]; int count = 0, word = 0;\\n    gets(s);\\n    for (int i = 0; s[i] != \'\\\\0\'; i++) {\\n        if (s[i] == \' \') word = 0;\\n        else if (word == 0) { word = 1; count++; }\\n    }\\n    printf(\\\"单词数:%d\\\\n\\\", count);\\n    return 0;\\n}\",\"explanation\":\"这是数组的经典程序。记忆要点：状态量 word 判定单词开头计数。\",\"codeLanguage\":\"c\",\"memoryAid\":\"状态量 word 判定单词开头计数。\"},{\"id\":58,\"type\":\"code\",\"category\":\"数组\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：输入4个国家的名字，按照从小到大的顺序进行排序并输出。\",\"options\":[],\"answer\":\"#include <stdio.h>\\n#include <string.h>\\nint main() {\\n    char country[4][50], temp[50];\\n    for (int i = 0; i < 4; i++) gets(country[i]);\\n    for (int i = 0; i < 3; i++) {\\n        for (int j = 0; j < 3 - i; j++) {\\n            if (strcmp(country[j], country[j+1]) > 0) {\\n                strcpy(temp, country[j]);\\n                strcpy(country[j], country[j+1]);\\n                strcpy(country[j+1], temp);\\n            }\\n        }\\n    }\\n    for (int i = 0; i < 4; i++) puts(country[i]);\\n    return 0;\\n}\",\"explanation\":\"这是数组的经典程序。记忆要点：二维字符数组，strcmp 比较，strcpy 交换。\",\"codeLanguage\":\"c\",\"memoryAid\":\"二维字符数组，strcmp 比较，strcpy 交换。\"},{\"id\":59,\"type\":\"code\",\"category\":\"数组\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：从键盘上任意输入一个字符串，将该字符串中的字符按照 ASCII 码的顺序从小到大的顺序排序后输出。\",\"options\":[],\"answer\":\"#include <stdio.h>\\n#include <string.h>\\nint main() {\\n    char s[100], t;\\n    gets(s); int len = strlen(s);\\n    for (int i = 0; i < len - 1; i++) {\\n        for (int j = 0; j < len - 1 - i; j++) {\\n            if (s[j] > s[j+1]) { t = s[j]; s[j] = s[j+1]; s[j+1] = t; }\\n        }\\n    }\\n    puts(s);\\n    return 0;\\n}\",\"explanation\":\"这是数组的经典程序。\",\"codeLanguage\":\"c\",\"memoryAid\":\"\"},{\"id\":60,\"type\":\"code\",\"category\":\"数组\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：任意输入一段英文，将其中所有的数字字符删除,再输出结果(采用的是后面的往前覆盖的思路设计)。\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    char s[200]; int j = 0;\\n    gets(s);\\n    for (int i = 0; s[i] != \'\\\\0\'; i++) {\\n        if (!(s[i] >= \'0\' && s[i] <= \'9\')) { s[j++] = s[i]; }\\n    }\\n    s[j] = \'\\\\0\';\\n    puts(s);\\n    return 0;\\n}\",\"explanation\":\"这是数组的经典程序。记忆要点：双指针覆盖。\",\"codeLanguage\":\"c\",\"memoryAid\":\"双指针覆盖。\"},{\"id\":61,\"type\":\"code\",\"category\":\"数组\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：编程实现输入一行字符，将其中重复出现的字符全部删除。\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    char s[200]; int visited[256] = {0};\\n    gets(s);\\n    for (int i = 0; s[i] != \'\\\\0\'; i++) {\\n        if (visited[(unsigned char)s[i]] == 0) {\\n            putchar(s[i]);\\n            visited[(unsigned char)s[i]] = 1;\\n        }\\n    }\\n    printf(\\\"\\\\n\\\");\\n    return 0;\\n}\",\"explanation\":\"这是数组的经典程序。记忆要点：大小 256 的 visited 状态数组去重法。\",\"codeLanguage\":\"c\",\"memoryAid\":\"大小 256 的 visited 状态数组去重法。\"},{\"id\":62,\"type\":\"code\",\"category\":\"数组\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：要将 \'China\' 译成密码，译码规律是：用原来字母后面的第4个字母代替原来的字母。\",\"options\":[],\"answer\":\"#include <stdio.h>\\nint main() {\\n    char s[] = \\\"China\\\";\\n    for (int i = 0; s[i] != \'\\\\0\'; i++) s[i] = s[i] + 4;\\n    puts(s);\\n    return 0;\\n}\",\"explanation\":\"这是数组的经典程序。\",\"codeLanguage\":\"c\",\"memoryAid\":\"\"},{\"id\":63,\"type\":\"code\",\"category\":\"数组\",\"difficulty\":2,\"question\":\"请默写以下程序的完整代码：\\n\\n**题目**：石头剪子布游戏结果判断。\",\"options\":[],\"answer\":\"#include <stdio.h>\\n#include <string.h>\\nint main() {\\n    char p1[10], p2[10];\\n    scanf(\\\"%s %s\\\", p1, p2);\\n    if (strcmp(p1, p2) == 0) printf(\\\"平局\\\\n\\\");\\n    else if ((strcmp(p1, \\\"石头\\\")==0 && strcmp(p2, \\\"剪刀\\\")==0) ||\\n             (strcmp(p1, \\\"剪刀\\\")==0 && strcmp(p2, \\\"布\\\")==0) ||\\n             (strcmp(p1, \\\"布\\\")==0 && strcmp(p2, \\\"石头\\\")==0)) {\\n        printf(\\\"玩家1获胜\\\\n\\\");\\n    } else {\\n        printf(\\\"玩家2获胜\\\\n\\\");\\n    }\\n    return 0;\\n}\",\"explanation\":\"这是数组的经典程序。\",\"codeLanguage\":\"c\",\"memoryAid\":\"\"}]','[\"review\"]',0,'2026-06-02T14:34:20.570Z','2026-06-13T13:57:06.348Z'),('c-language-basics','C语言基础','C语言程序设计基础题库（含图片识别导入题目）','',16,237,'[{\"id\":1,\"type\":\"single\",\"category\":\"基础语法\",\"tags\":[\"变量命名\"],\"difficulty\":1,\"question\":\"以下哪个是C语言的合法标识符？\",\"options\":[\"A. `123var`\",\"B. `_count`\",\"C. `int`\",\"D. `my-var`\"],\"answer\":\"B\",\"explanation\":\"标识符命名规则：\\n1. 由字母、数字、下划线组成\\n2. 不能以数字开头\\n3. 不能是关键字（如 `int`）\\n4. 不能包含特殊字符（如 `-`）\",\"memoryAid\":\"标识字母下划线，数字开头不能用，关键字和横杠，统统都是不合法\"},{\"id\":2,\"type\":\"single\",\"category\":\"数据类型\",\"tags\":[\"sizeof\"],\"difficulty\":1,\"question\":\"在32位系统中，`sizeof(int)` 的值通常是？\",\"options\":[\"A. 2\",\"B. 4\",\"C. 8\",\"D. 不确定\"],\"answer\":\"B\",\"explanation\":\"在大多数32位和64位系统中，`int` 占4字节（32位）。但C标准只保证 `sizeof(int) >= 2`。\",\"code\":\"#include <stdio.h>\\nint main() {\\n    printf(\\\"%zu\\\\n\\\", sizeof(int));\\n    return 0;\\n}\",\"codeLanguage\":\"c\",\"memoryAid\":\"int四字节三二位，sizeof牢记别搞错，六四系统也一样，四字节是默认值\"},{\"id\":3,\"type\":\"single\",\"category\":\"数据类型\",\"tags\":[\"类型转换\"],\"difficulty\":2,\"question\":\"以下代码的输出结果是？\\n```c\\nint a = 5;\\ndouble b = a / 2;\\nprintf(\\\"%.1f\\\", b);\\n```\",\"options\":[\"A. `2.5`\",\"B. `2.0`\",\"C. `3.0`\",\"D. 编译错误\"],\"answer\":\"B\",\"explanation\":\"`5 / 2` 是整数除法，结果为 `2`，然后赋值给 `double` 变为 `2.0`。要得到 `2.5` 需要 `5.0 / 2` 或 `(double)a / 2`。\",\"code\":\"#include <stdio.h>\\nint main() {\\n    int a = 5;\\n    double b = a / 2;\\n    printf(\\\"%.1f\\\", b);  // 输出 2.0\\n    \\n    double c = a / 2.0;\\n    printf(\\\"%.1f\\\", c);  // 输出 2.5\\n    return 0;\\n}\",\"codeLanguage\":\"c\",\"memoryAid\":\"整数除法取整数，五除二得二非二五，想得小数先转型，浮点参与才正确\"},{\"id\":4,\"type\":\"single\",\"category\":\"控制结构\",\"tags\":[\"循环\"],\"difficulty\":2,\"question\":\"以下代码执行后，`sum` 的值是？\\n```c\\nint sum = 0;\\nfor (int i = 1; i <= 100; i++) {\\n    sum += i;\\n}\\n```\",\"options\":[\"A. `4950`\",\"B. `5000`\",\"C. `5050`\",\"D. `5100`\"],\"answer\":\"C\",\"explanation\":\"这是一个等差数列求和：$1 + 2 + 3 + ... + 100 = \\\\frac{100 \\\\times 101}{2} = 5050$\",\"memoryAid\":\"一加到百五零五零，百乘百一除以二，等差求和公式记，for循环跑出它\"},{\"id\":5,\"type\":\"multiple\",\"category\":\"数据类型\",\"tags\":[\"基本类型\"],\"difficulty\":1,\"question\":\"以下哪些是C语言的基本数据类型？\",\"options\":[\"A. `int`\",\"B. `float`\",\"C. `string`\",\"D. `char`\"],\"answer\":[\"A\",\"B\",\"D\"],\"explanation\":\"C语言基本数据类型包括：\\n- 整型：`int`, `short`, `long`, `long long`\\n- 浮点型：`float`, `double`\\n- 字符型：`char`\\n- 空类型：`void`\\n\\nC语言没有内置的 `string` 类型，字符串用字符数组表示。\",\"memoryAid\":\"基本类型三兄弟，int整数float浮，char字符莫忘记，string不是C本家\"},{\"id\":6,\"type\":\"judge\",\"category\":\"基础语法\",\"tags\":[\"注释\"],\"difficulty\":1,\"question\":\"C语言支持 `//` 单行注释和 `/* */` 多行注释。\",\"options\":[],\"answer\":true,\"explanation\":\"C99标准开始支持 `//` 单行注释。`/* */` 是传统的C语言注释方式。\",\"memoryAid\":\"双斜杠注单行，斜杠星号注多行，C九九前只有星，双斜杠是后来人\"},{\"id\":7,\"type\":\"fill\",\"category\":\"基础语法\",\"tags\":[\"输入输出\"],\"difficulty\":2,\"question\":\"在 `printf` 中，`%d` 用于输出 `int` 类型，`%f` 用于输出 `float` 或 `double` 类型，`%c` 用于输出 `char` 类型。\",\"options\":[],\"answer\":[\"%d\",\"%f\",\"%c\"],\"explanation\":\"常用格式说明符：\\n- `%d` 或 `%i`：整数\\n- `%f`：浮点数\\n- `%c`：字符\\n- `%s`：字符串\\n- `%p`：指针地址\\n- `%x`：十六进制\",\"memoryAid\":\"百分d输出整数，百分f输出浮点，百分c输出字符，格式符要配对用\"},{\"id\":8,\"type\":\"single\",\"category\":\"数组\",\"tags\":[\"数组定义\"],\"difficulty\":2,\"question\":\"以下哪个正确定义了一个包含10个元素的整型数组？\",\"options\":[\"A. `int arr[10];`\",\"B. `int arr(10);`\",\"C. `int arr[] = 10;`\",\"D. `int[10] arr;`\"],\"answer\":\"A\",\"explanation\":\"C语言数组定义语法：`类型 数组名[大小];`\\n\\n注意：\\n- 使用方括号 `[]`，不是圆括号\\n- 大小必须是常量表达式（C99之前）\",\"code\":\"#include <stdio.h>\\nint main() {\\n    int arr[10];  // 定义10个元素的数组\\n    \\n    // 初始化数组\\n    for (int i = 0; i < 10; i++) {\\n        arr[i] = i * 2;\\n    }\\n    \\n    // 打印数组\\n    for (int i = 0; i < 10; i++) {\\n        printf(\\\"%d \\\", arr[i]);\\n    }\\n    return 0;\\n}\",\"codeLanguage\":\"c\",\"memoryAid\":\"数组定义用方括，int arr后跟十，圆括号是错写法，类型数组名大小\"},{\"id\":9,\"type\":\"single\",\"category\":\"指针\",\"tags\":[\"指针基础\"],\"difficulty\":3,\"question\":\"以下代码的输出是？\\n```c\\nint x = 10;\\nint *p = &x;\\n*p = 20;\\nprintf(\\\"%d\\\", x);\\n```\",\"options\":[\"A. `10`\",\"B. `20`\",\"C. 地址值\",\"D. 编译错误\"],\"answer\":\"B\",\"explanation\":\"`p` 是指向 `x` 的指针，`*p = 20` 通过指针修改了 `x` 的值。所以 `x` 变成了 `20`。\\n\\n指针操作：\\n- `&`：取地址运算符\\n- `*`：解引用运算符\",\"code\":\"#include <stdio.h>\\nint main() {\\n    int x = 10;\\n    int *p = &x;    // p 指向 x\\n    \\n    printf(\\\"x = %d\\\\n\\\", x);      // 10\\n    printf(\\\"*p = %d\\\\n\\\", *p);    // 10\\n    \\n    *p = 20;  // 通过指针修改 x\\n    printf(\\\"x = %d\\\\n\\\", x);      // 20\\n    \\n    return 0;\\n}\",\"codeLanguage\":\"c\",\"memoryAid\":\"指针星号取变量，p指向x的地址，星p等于二十改，x的值也跟着变\"},{\"id\":10,\"type\":\"single\",\"category\":\"函数\",\"tags\":[\"函数定义\"],\"difficulty\":2,\"question\":\"以下哪个是正确的函数声明？\",\"options\":[\"A. `int add(int a, b);`\",\"B. `int add(int a, int b);`\",\"C. `add(int a, int b) int;`\",\"D. `int add(a, b);`\"],\"answer\":\"B\",\"explanation\":\"函数声明语法：`返回类型 函数名(参数类型 参数名, ...);`\\n\\n每个参数都必须单独指定类型。\",\"code\":\"#include <stdio.h>\\n\\n// 函数声明\\nint add(int a, int b);\\n\\n// 函数定义\\nint add(int a, int b) {\\n    return a + b;\\n}\\n\\nint main() {\\n    int result = add(3, 5);\\n    printf(\\\"3 + 5 = %d\\\", result);\\n    return 0;\\n}\",\"codeLanguage\":\"c\",\"memoryAid\":\"函数声明要规范，每个参数类型写，int a逗号int b，类型名字都不能缺\"},{\"type\":\"single\",\"category\":\"程序结构\",\"tags\":[\"图片识别\",\"习题1-1\"],\"difficulty\":1,\"question\":\"一个 C 程序的执行是从（ ）。\",\"options\":[\"A. 本程序的 main 函数开始，到 main 函数结束\",\"B. 本程序文件的第一个函数开始，到本程序文件的最后一个函数结束\",\"C. 本程序的 main 函数开始，到本程序文件的最后一个函数结束\",\"D. 本程序文件的第一个函数开始，到本程序 main 函数结束\"],\"answer\":\"A\",\"explanation\":\"本题考查程序结构。正确答案是 A。\",\"source\":\"夸克扫描王_该函数使用输出(1).jpeg\",\"id\":11,\"memoryAid\":\"程序入口是main，从它开始到它终，不管函数怎么排，main就是出发点\"},{\"type\":\"single\",\"category\":\"程序结构\",\"tags\":[\"图片识别\",\"习题1-2\"],\"difficulty\":1,\"question\":\"在 C 语言中，每个语句必须以（ ）结束。\",\"options\":[\"A. 回车符\",\"B. 冒号\",\"C. 逗号\",\"D. 分号\"],\"answer\":\"D\",\"explanation\":\"本题考查程序结构。正确答案是 D。手写答案形似 D/括号，按题意校验为 D。\",\"source\":\"夸克扫描王_该函数使用输出(1).jpeg\",\"id\":12,\"memoryAid\":\"语句结尾用分号，回车冒号逗号都不行，分号是C的句号，每句必加别忘记\"},{\"type\":\"single\",\"category\":\"程序结构\",\"tags\":[\"图片识别\",\"习题1-3\"],\"difficulty\":1,\"question\":\"C 语言规定：在一个源程序中，main 函数的位置（ ）。\",\"options\":[\"A. 必须在最开始\",\"B. 必须在系统调用的库函数后面\",\"C. 可以任意\",\"D. 必须在最后\"],\"answer\":\"C\",\"explanation\":\"本题考查程序结构。正确答案是 C。题目跨图片：A/B 在第1张，C/D 在第2张。\",\"source\":\"夸克扫描王_该函数使用输出(1).jpeg; 夸克扫描王_该函数使用输出(2).jpeg\",\"id\":13,\"memoryAid\":\"main位置不固定，放前放后都可行，程序执行认main，位置任意不强求\"},{\"type\":\"single\",\"category\":\"程序结构\",\"tags\":[\"图片识别\",\"习题1-4\"],\"difficulty\":1,\"question\":\"一个 C 语言程序是由（ ）。\",\"options\":[\"A. 一个主程序和若干子程序组成\",\"B. 函数组成\",\"C. 若干过程组成\",\"D. 若干子程序组成\"],\"answer\":\"B\",\"explanation\":\"本题考查程序结构。正确答案是 B。\",\"source\":\"夸克扫描王_该函数使用输出(2).jpeg\",\"id\":14,\"memoryAid\":\"C程序由函数组，不是主程序子程序，函数是基本单位，一个程序函数多\"},{\"type\":\"single\",\"category\":\"程序结构\",\"tags\":[\"图片识别\",\"习题1-5\"],\"difficulty\":1,\"question\":\"下列说法中错误的是（ ）。\",\"options\":[\"A. 主函数可以分为两个部分：主函数说明部分和主函数体\",\"B. 主函数可以调用任何非主函数的其他函数\",\"C. 任何非主函数可以调用其他任何非主函数\",\"D. 程序可以从任何非主函数开始执行\"],\"answer\":\"D\",\"explanation\":\"本题考查程序结构。正确答案是 D。C 程序从 main 函数开始执行。\",\"source\":\"夸克扫描王_该函数使用输出(2).jpeg\",\"id\":15,\"memoryAid\":\"程序执行main始，任何非main不能起，主函数是总指挥，程序从它开始跑\"},{\"type\":\"single\",\"category\":\"程序结构\",\"tags\":[\"图片识别\",\"习题1-6\"],\"difficulty\":3,\"question\":\"用 C 语言编写的源文件经过编译，若没有产生编译错误，则系统将（ ）。\",\"options\":[\"A. 生成可执行目标文件\",\"B. 生成目标文件\",\"C. 输出运行结果\",\"D. 自动保存源文件\"],\"answer\":\"A\",\"explanation\":\"本题考查程序结构。正确答案是 A。严格区分编译/链接时，编译通常生成目标文件，链接后才生成可执行文件；本题教材语境似将构建过程统称为编译。\",\"source\":\"夸克扫描王_该函数使用输出(2).jpeg\",\"id\":16,\"memoryAid\":\"编译成功出目标，链接之后才可执行，两步分开要记牢，目标文件非最终\"},{\"type\":\"single\",\"category\":\"程序结构\",\"tags\":[\"图片识别\",\"习题1-7\"],\"difficulty\":1,\"question\":\"main() 函数为主函数，一个 C 程序总是从 main() 函数开始执行的。在关于 C 语言的网站和图书中可以看到 main 函数的多种格式，看过资料后，下列哪个不推荐使用（ ）？\",\"options\":[\"A. int main(void)\",\"B. int main()\",\"C. void main()\",\"D. int main(int argc, char *argv[])\"],\"answer\":\"C\",\"explanation\":\"本题考查程序结构。正确答案是 C。标准 C 中 main 应返回 int。\",\"source\":\"夸克扫描王_该函数使用输出(2).jpeg\",\"id\":17,\"memoryAid\":\"main返回要int，void main不推荐，标准写法有规范，返回类型不能缺\"},{\"type\":\"single\",\"category\":\"程序结构\",\"tags\":[\"图片识别\",\"习题1-8\"],\"difficulty\":1,\"question\":\"下面有关 C 语言特点的说法中，错误的是（ ）。\",\"options\":[\"A. C 语言编写的代码较为紧凑，执行速度也较快\",\"B. C 语言不仅适合编写各种应用软件，还适于编写各种系统软件\",\"C. C 语言是一种模块化和结构化的语言\",\"D. C 语言编写的程序通常不具备移植性\"],\"answer\":\"D\",\"explanation\":\"本题考查程序结构。正确答案是 D。C 程序通常具有较好的可移植性。\",\"source\":\"夸克扫描王_该函数使用输出(2).jpeg\",\"id\":18,\"memoryAid\":\"C语言移植性好，跨平台编译能运行，紧凑高效又灵活，系统应用都能写\"},{\"type\":\"single\",\"category\":\"程序结构\",\"tags\":[\"图片识别\",\"习题1-9\"],\"difficulty\":1,\"question\":\"下面有关 C 程序操作过程的说法中，错误的是（ ）。\",\"options\":[\"A. C 源程序经过编译，得到的目标文件即为可执行文件\",\"B. C 源程序的链接实质上是将目标代码文件和库函数等代码进行连接的过程\",\"C. C 源程序不能通过编译，通常是由于语法错误引起的\",\"D. 不能得到预期计算结果的主要原因是程序算法考虑不周\"],\"answer\":\"A\",\"explanation\":\"本题考查程序结构。正确答案是 A。目标文件还需链接才成为可执行文件。\",\"source\":\"夸克扫描王_该函数使用输出(2).jpeg\",\"id\":19,\"memoryAid\":\"目标文件非可执行，还需链接库函数，编译链接两步走，缺了链接跑不了\"},{\"type\":\"single\",\"category\":\"程序结构\",\"tags\":[\"图片识别\",\"习题1-10\"],\"difficulty\":1,\"question\":\"以下叙述中正确的是（ ）。\",\"options\":[\"A. 在 C 程序中，main 函数必须位于程序的最前面\",\"B. C 程序的每一行中只能写一条语句\",\"C. 在对一个 C 程序进行编译的过程中，可发现注释中的拼写错误\",\"D. C 语言本身没有输入输出语句\"],\"answer\":\"D\",\"explanation\":\"本题考查程序结构。正确答案是 D。输入输出由库函数提供，不是 C 语言语句。\",\"source\":\"夸克扫描王_该函数使用输出(2).jpeg\",\"id\":20,\"memoryAid\":\"输入输出靠函数，printf scanf非语句，C语言本身无IO，库函数来帮助你\"},{\"type\":\"single\",\"category\":\"程序结构\",\"tags\":[\"图片识别\",\"习题1-11\"],\"difficulty\":3,\"question\":\"以下叙述中正确的是（ ）。\",\"options\":[\"A. C 程序的基本组成单位是语句\",\"B. C 程序中的每一行中只能写一条语句\",\"C. C 语句必须以分号结束\",\"D. C 语句必须在一行内写完\"],\"answer\":\"C\",\"explanation\":\"本题考查程序结构。正确答案是 C。按教材基础题口径，C 语句通常以分号结束；严格说复合语句等不以分号结束。\",\"source\":\"夸克扫描王_该函数使用输出(2).jpeg\",\"id\":21,\"memoryAid\":\"C语句必以分号结，一行可写多语句，复合语句花括号，分号是句的标志\"},{\"type\":\"single\",\"category\":\"程序结构\",\"tags\":[\"图片识别\",\"习题1-12\"],\"difficulty\":1,\"question\":\"以下叙述中错误的是（ ）。\",\"options\":[\"A. 函数是 C 程序的基本组成单位\",\"B. 函数体一般由一组 C 语句序列组成\",\"C. printf 是 C 语言提供的输出语句\",\"D. 函数通常分为库函数和用户自定义函数两种\"],\"answer\":\"C\",\"explanation\":\"本题考查程序结构。正确答案是 C。printf 是标准库函数，不是 C 语言语句。\",\"source\":\"夸克扫描王_该函数使用输出(2).jpeg\",\"id\":22,\"memoryAid\":\"printf是库函数，不是C语言的语句，函数分库和自定义，基本单位是函数\"},{\"type\":\"single\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-1\"],\"difficulty\":1,\"question\":\"下列标识符中，不合法的用户标识符为（ ）。\",\"options\":[\"A. aBa\",\"B. _11\",\"C. a_1\",\"D. a&b\"],\"answer\":\"D\",\"explanation\":\"本题考查数据类型与表达式。正确答案是 D。& 不能出现在标识符中。\",\"source\":\"夸克扫描王_该函数使用输出(3).jpeg\",\"id\":23,\"memoryAid\":\"标识符里不能有&，特殊符号要提防，下划线字母数字可以放\"},{\"type\":\"single\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-2\"],\"difficulty\":1,\"question\":\"下列标识符中，合法的用户标识符为（ ）。\",\"options\":[\"A. month\",\"B. 5xy\",\"C. int\",\"D. your name\"],\"answer\":\"A\",\"explanation\":\"本题考查数据类型与表达式。正确答案是 A。\",\"source\":\"夸克扫描王_该函数使用输出(4).jpeg\",\"id\":24,\"memoryAid\":\"标识符首字不能数字，关键字不能当名字，空格出现不合规\"},{\"type\":\"single\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-3\"],\"difficulty\":1,\"question\":\"（ ）是 C 语言提供的合法的数据类型关键字。\",\"options\":[\"A. Boolean\",\"B. signed\",\"C. integer\",\"D. Char\"],\"answer\":\"B\",\"explanation\":\"本题考查数据类型与表达式。正确答案是 B。C 关键字区分大小写。\",\"source\":\"夸克扫描王_该函数使用输出(4).jpeg\",\"id\":25,\"memoryAid\":\"C语言关键字分大小，Boolean大写不认账，signed小写才合法\"},{\"type\":\"single\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-4\"],\"difficulty\":1,\"question\":\"不合法的字符常量是（ ）。\",\"options\":[\"A. \'\\\\678\'\",\"B. \'\\\\\\\"\'\",\"C. \' \'\",\"D. \'\\\\4\'\"],\"answer\":\"A\",\"explanation\":\"本题考查数据类型与表达式。正确答案是 A。A 中八进制转义含 8。\",\"source\":\"夸克扫描王_该函数使用输出(4).jpeg\",\"id\":26,\"memoryAid\":\"八进制转义零到七，碰上数字八就不行，\\\\678里8非法记分明\"},{\"type\":\"single\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-5\"],\"difficulty\":1,\"question\":\"不正确的字符串常量是（ ）。\",\"options\":[\"A. \'abc\'\",\"B. \\\"12\'12\\\"\",\"C. \\\"0\\\"\",\"D. \\\" \\\"\"],\"answer\":\"A\",\"explanation\":\"本题考查数据类型与表达式。正确答案是 A。单引号表示字符常量，不是字符串常量。\",\"source\":\"夸克扫描王_该函数使用输出(4).jpeg\",\"id\":27,\"memoryAid\":\"单引字符双引串，\'abc\'单引不算串，字符串必须双引框\"},{\"type\":\"single\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-6\"],\"difficulty\":1,\"question\":\"以下选项中合法的标识符是（ ）。\",\"options\":[\"A. 1_1\",\"B. 1-1\",\"C. _11\",\"D. 1_\"],\"answer\":\"C\",\"explanation\":\"本题考查数据类型与表达式。正确答案是 C。标识符不能以数字开头，不能含减号。\",\"source\":\"夸克扫描王_该函数使用输出(4).jpeg\",\"id\":28,\"memoryAid\":\"标识符开头禁数字，减号连字符也不能，下划线打头最安全\"},{\"type\":\"single\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-7\"],\"difficulty\":1,\"question\":\"下列关于 C 语言用户标识符的叙述中正确的是（ ）。\",\"options\":[\"A. 用户标识符中可以出现下划线和中划线（减号）\",\"B. 用户标识符中不可以出现中划线，但可以出现下划线\",\"C. 用户标识符中可以出现下划线，但不可以放在用户标识符的开头\",\"D. 用户标识符中可以出现下划线和数字，它们都可以放在用户标识符的开头\"],\"answer\":\"B\",\"explanation\":\"本题考查数据类型与表达式。正确答案是 B。下划线可用，减号不可用；数字不能作为开头。\",\"source\":\"夸克扫描王_该函数使用输出(4).jpeg\",\"id\":29,\"memoryAid\":\"下划线随意减号禁，数字开头不可以，标识符规则牢记心\"},{\"type\":\"single\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-8\"],\"difficulty\":1,\"question\":\"C 语言中，最基本的数据类型是（ ）。\",\"options\":[\"A. 整型、实型、逻辑型\",\"B. 整型、实型、字符型\",\"C. 整型、字符型、逻辑型\",\"D. 整型、实型、逻辑型、字符型\"],\"answer\":\"B\",\"explanation\":\"本题考查数据类型与表达式。正确答案是 B。按传统 C 基础教材分类。\",\"source\":\"夸克扫描王_该函数使用输出(4).jpeg\",\"id\":30,\"memoryAid\":\"C语言三类基本型，整型实型字符型，没有逻辑型的份\"},{\"type\":\"single\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-9\"],\"difficulty\":1,\"question\":\"下面有关变量声明的说法中，正确的是（ ）。\",\"options\":[\"A. C 语言中不用先声明变量，需要时直接使用即可\",\"B. 每个变量的存储空间大小由数据类型和编译环境共同决定\",\"C. 在 Code::Blocks 环境下，为 int 型变量分配的存储空间大小为 2 个字节\",\"D. 变量声明时，不能进行赋值操作\"],\"answer\":\"B\",\"explanation\":\"本题考查数据类型与表达式。正确答案是 B。\",\"source\":\"夸克扫描王_该函数使用输出(4).jpeg\",\"id\":31,\"memoryAid\":\"变量空间大小谁决定，数据类型编译环境，二者合力才搞定\"},{\"type\":\"single\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-10\"],\"difficulty\":2,\"question\":\"关于下面的程序，正确的说法是（ ）。\\n```c\\n#include <stdio.h>\\nint main(){\\n    float a = b = 2, result;\\n    result = a / b;\\n    printf(\\\"result = %f\\\\n\\\", result);\\n    return 0;\\n}\\n```\",\"options\":[\"A. 程序可正常编译，结果为 result = 1.000000\",\"B. 共有 1 处语法错误\",\"C. 共有 2 处语法错误\",\"D. 共有 3 处语法错误\"],\"answer\":\"C\",\"explanation\":\"本题考查数据类型与表达式。正确答案是 C。主要错误为 include 写法错误，以及 b 未声明即在初始化表达式中使用。\",\"source\":\"夸克扫描王_该函数使用输出(4).jpeg\",\"id\":32,\"memoryAid\":\"include尖括号不能漏，变量声明要先有，float a=b错在先使用b\"},{\"type\":\"single\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-11\"],\"difficulty\":1,\"question\":\"下面变量声明的语句中，错误的是（ ）。\",\"options\":[\"A. char c = B;\",\"B. int a = 3;\",\"C. char c = 65;\",\"D. float area = 0;\"],\"answer\":\"A\",\"explanation\":\"本题考查数据类型与表达式。正确答案是 A。B 未加引号，若无变量 B 则不能作为字符初值。\",\"source\":\"夸克扫描王_该函数使用输出(4).jpeg\",\"id\":33,\"memoryAid\":\"字符赋值要引号，B没引号变变量名，char c=65反而行\"},{\"type\":\"single\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-12\"],\"difficulty\":2,\"question\":\"关于下面的程序，正确的说法是（ ）。\\n```c\\n#include <stdio.h>\\nint main(){\\n    int x, y, z; x = y = z = 1;\\n    printf(\\\"x = %d,y = %d,z = %d\\\\n\\\", x, y, z);\\n    return 0;\\n}\\n```\",\"options\":[\"A. 程序无误，能正常通过编译\",\"B. #inelude <stdio.h> 有误，需改为 #include \\\"stdio.h\\\"\",\"C. int x,y,z; 有误，需改为 int x;y;z;\",\"D. x = y = z = 1; 有误，需改为 x = 1; y = 1; z = 1;\"],\"answer\":\"A\",\"explanation\":\"本题考查数据类型与表达式。正确答案是 A。\",\"source\":\"夸克扫描王_该函数使用输出(4).jpeg; 夸克扫描王_该函数使用输出(5).jpeg\",\"id\":34,\"memoryAid\":\"链式赋值x=y=z=1，C语言完全允许干，语法正确不用管\"},{\"type\":\"single\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-13\"],\"difficulty\":1,\"question\":\"已知字母 A 的 ASCII 码为十进制数 65，且 c2 为字符型，则执行语句 c2 = \'A\' + \'6\' - \'2\'; 后，c2 中的值为（ ）。\",\"options\":[\"A. 69\",\"B. C\",\"C. D\",\"D. E\"],\"answer\":\"A\",\"explanation\":\"本题考查数据类型与表达式。正确答案是 A。表达式数值为 65 + 54 - 50 = 69；若按字符显示则为 \'E\'，但选项按数值取 A。\",\"source\":\"夸克扫描王_该函数使用输出(5).jpeg\",\"id\":35,\"memoryAid\":\"ASCII码运算做加减，\'A\'加\'6\'减\'2\'等于69，数值结果记心间\"},{\"type\":\"single\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-14\"],\"difficulty\":1,\"question\":\"为了计算 s = 10!，则定义变量 s 时应该使用的数据类型是（ ）。\",\"options\":[\"A. int\",\"B. unsigned\",\"C. long\",\"D. 以上三种类型均可\"],\"answer\":\"C\",\"explanation\":\"本题考查数据类型与表达式。正确答案是 C。10! = 3628800；按 C 标准最小范围，long 能保证容纳，int/unsigned 不一定。\",\"source\":\"夸克扫描王_该函数使用输出(5).jpeg\",\"id\":36,\"memoryAid\":\"十的阶乘三百六十二万八千八，int不够long来担，大数存储long稳\"},{\"type\":\"single\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-15\"],\"difficulty\":1,\"question\":\"以下选项中，能用作数据常量的是（ ）。\",\"options\":[\"A. 0119\",\"B. o126\",\"C. 2.5e2.5\",\"D. 119L\"],\"answer\":\"D\",\"explanation\":\"本题考查数据类型与表达式。正确答案是 D。A 非法八进制，B 以字母 o 开头，C 指数部分非法。\",\"source\":\"夸克扫描王_该函数使用输出(5).jpeg\",\"id\":37,\"memoryAid\":\"八进制零开头不能九，字母o开头也不行，指数必须是整数，L后缀合法记心头\"},{\"type\":\"single\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-16\"],\"difficulty\":1,\"question\":\"以下关于 short、int 和 long 类型数据占用内存大小的叙述中正确的是（ ）。\",\"options\":[\"A. 均占 4 个字节\",\"B. 根据数据的大小决定所占内存的字节数\",\"C. 由用户自己定义\",\"D. 由 C 语言编译系统决定\"],\"answer\":\"D\",\"explanation\":\"本题考查数据类型与表达式。正确答案是 D。整数类型大小由实现决定。\",\"source\":\"夸克扫描王_该函数使用输出(5).jpeg\",\"id\":38,\"memoryAid\":\"整数类型大小谁说了，不是用户不是值，编译系统它来定\"},{\"type\":\"single\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-17\"],\"difficulty\":1,\"question\":\"若已定义 char c = \'\\\\010\'，则变量 c 所占的字节数为（ ）。\",\"options\":[\"A. 1\",\"B. 2\",\"C. 3\",\"D. 4\"],\"answer\":\"A\",\"explanation\":\"本题考查数据类型与表达式。正确答案是 A。char 对象大小为 1 字节。\",\"source\":\"夸克扫描王_该函数使用输出(5).jpeg\",\"id\":39,\"memoryAid\":\"char类型占一字节，不管初值写多长，一个字节稳如桩\"},{\"type\":\"multiple\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-18\"],\"difficulty\":1,\"question\":\"要定义双精度实型变量 a 和 b，并初始化为数值 7，则正确的语句是（ ）。\",\"options\":[\"A. double a, b; a = b = 7;\",\"B. double a = b = 7;\",\"C. double a = b = \'7\';\",\"D. double a = 7, b = 7;\"],\"answer\":[\"A\",\"D\"],\"explanation\":\"本题考查数据类型与表达式。正确答案是 A、D。该题有两个正确选项。\",\"source\":\"夸克扫描王_该函数使用输出(5).jpeg\",\"id\":40,\"memoryAid\":\"double初始化有两种，分开声明再赋值，或者逗号隔开并排写\"},{\"type\":\"single\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-19\"],\"difficulty\":2,\"question\":\"以下程序运行后的输出结果是（ ）。\\n```c\\n#include \\\"stdio.h\\\"\\nint main(){\\n    char c;\\n    c = \'B\' + 32;\\n    printf(\\\"%c\\\\n\\\", c);\\n    return 0;\\n}\\n```\",\"options\":[\"A. B\",\"B. b\",\"C. B32\",\"D. b32\"],\"answer\":\"B\",\"explanation\":\"本题考查数据类型与表达式。正确答案是 B。图片中 printf 的实参字形略像 m，按上下文应为 c；若真为 m 则会编译出错。\",\"source\":\"夸克扫描王_该函数使用输出(5).jpeg\",\"id\":41,\"memoryAid\":\"大小写字母差三十二，B加三十二变成b，小写转换这个理\"},{\"type\":\"single\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-20\"],\"difficulty\":2,\"question\":\"以下程序运行后的输出结果是（ ）。\\n```c\\n#include \\\"stdio.h\\\"\\nint main(){\\n    char c1, c2; c1 = \'a\'; c2 = \'b\';\\n    c1 = c1 - 32;\\n    c2 = c2 - 32;\\n    printf(\\\"%c %c\\\\n\\\", c1, c2);\\n    printf(\\\"%d %d\\\\n\\\", c1, c2);\\n    return 0;\\n}\\n```\",\"options\":[\"A. A  B\\\\n65 66\",\"B. A  B\\\\n97 98\",\"C. a  b\\\\n65 66\",\"D. a  b\\\\n97 98\"],\"answer\":\"A\",\"explanation\":\"本题考查数据类型与表达式。正确答案是 A。题目跨图片：程序前半在第5张，后半及选项在第6张。\",\"source\":\"夸克扫描王_该函数使用输出(5).jpeg; 夸克扫描王_该函数使用输出(6).jpeg\",\"id\":42,\"memoryAid\":\"小写减三十二变大写，%c输出字符样，%d输出数字量\"},{\"type\":\"single\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-21\"],\"difficulty\":1,\"question\":\"如果将一个函数的返回值类型说明为 void，则表示（ ）。\",\"options\":[\"A. 该函数可以返回任意类型的值\",\"B. 该函数不能返回任何值\",\"C. 该函数可以返回基本类型的值\",\"D. 该函数是 main 函数，是程序运行的起点\"],\"answer\":\"B\",\"explanation\":\"本题考查数据类型与表达式。正确答案是 B。\",\"source\":\"夸克扫描王_该函数使用输出(6).jpeg\",\"id\":43,\"memoryAid\":\"void函数无返回，声明void就是不给值，别在里面用return\"},{\"type\":\"single\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-22\"],\"difficulty\":1,\"question\":\"对于 int 型常量，不正确的是（ ）。\",\"options\":[\"A. 029\",\"B. -25\",\"C. 0x2A\",\"D. -0X28\"],\"answer\":\"A\",\"explanation\":\"本题考查数据类型与表达式。正确答案是 A。以 0 开头为八进制，不能含数字 9。\",\"source\":\"夸克扫描王_该函数使用输出(6).jpeg\",\"id\":44,\"memoryAid\":\"八进制常量零开头，里面数字零到七，出现九就犯了规\"},{\"type\":\"single\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-23\"],\"difficulty\":3,\"question\":\"下列整型常量，错误的是（ ）。\",\"options\":[\"A. 025\",\"B. 285L\",\"C. -285u（u 表示无符号，怎么还有负号）\",\"D. 285lu\"],\"answer\":\"C\",\"explanation\":\"本题考查数据类型与表达式。正确答案是 C。严格 C 词法中 -285u 可看作一元负号作用于无符号常量表达式；教材按“无符号常量不应带负号”判 C。\",\"source\":\"夸克扫描王_该函数使用输出(6).jpeg\",\"id\":45,\"memoryAid\":\"无符号常量u后缀，前面不能带负号，负号无符号自相矛盾\"},{\"type\":\"single\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-24\"],\"difficulty\":3,\"question\":\"以下有关整型变量的定义中，错误的是（ ）。\",\"options\":[\"A. short int x;\",\"B. long x;\",\"C. unsigned x;\",\"D. short x;\"],\"answer\":\"C\",\"explanation\":\"unsigne 是错误的（不完整且语法非法）；若原意为 ‌unsigned x;‌，则 ‌该定义也错误‌，因为 unsigned 不能单独用作类型，必须写为 unsigned int x。‌‌\\n\\n‌A. short int x;‌：合法，短整型定义。\\n‌B. long x;‌：合法，等价于 long int x;。\\n‌C. unsigne‌：拼写不完整（应为 unsigned），且即使补全为 unsigned x;，在C/C++中仍非法（缺少 int，应写 unsigned int x）。‌‌\\n完整正确的无符号整型定义必须包含 int（如 unsigned int x），unsigned 本身不是完整类型说明符。‌‌\",\"source\":\"夸克扫描王_该函数使用输出(6).jpeg\",\"id\":46,\"memoryAid\":\"short int完全合法，short就是short int，两种写法都正确\"},{\"type\":\"single\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-25\"],\"difficulty\":1,\"question\":\"下列实型常量，错误的是（ ）。\",\"options\":[\"A. 3.2f\",\"B. -2.2E-2F\",\"C. -12.0\",\"D. e3\"],\"answer\":\"D\",\"explanation\":\"本题考查数据类型与表达式。正确答案是 D。指数形式前必须有数字部分。\",\"source\":\"夸克扫描王_该函数使用输出(6).jpeg\",\"id\":47,\"memoryAid\":\"实型常量指数形式，数字部分不能省，e3缺少前半截\"},{\"type\":\"single\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-26\"],\"difficulty\":1,\"question\":\"在 Code::Blocks 环境下，sizeof(int) 和 sizeof(float) 的值分别为（ ）。\",\"options\":[\"A. 2,2\",\"B. 2,4\",\"C. 4,4\",\"D. 4,8\"],\"answer\":\"C\",\"explanation\":\"本题考查数据类型与表达式。正确答案是 C。具体大小与环境有关；题目限定 Code::Blocks。\",\"source\":\"夸克扫描王_该函数使用输出(6).jpeg\",\"id\":48,\"memoryAid\":\"Code::Blocks环境下，int四字节float四，sizeof测量不出奇\"},{\"type\":\"single\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-27\"],\"difficulty\":1,\"question\":\"对于浮点型数据，下列说法中不正确的是（ ）。\",\"options\":[\"A. 浮点数在存储时存在舍入误差\",\"B. 程序设计时，不能直接对两个浮点型数据进行相等比较\",\"C. 将一个很小的浮点数和一个很大的浮点数进行相加，结果可能不正确\",\"D. C 语言中的浮点型变量有 float 和 double 两种\"],\"answer\":\"D\",\"explanation\":\"本题考查数据类型与表达式。正确答案是 D。C 还有 long double。\",\"source\":\"夸克扫描王_该函数使用输出(6).jpeg\",\"id\":49,\"memoryAid\":\"浮点类型有三种，float和double还有long double，说只有两种就不对\"},{\"type\":\"single\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-28\"],\"difficulty\":1,\"question\":\"若 ch 为字符型变量，则不能使 ch 表示字符 \'B\' 的语句是（ ）。\",\"options\":[\"A. ch = B;\",\"B. ch = 66;\",\"C. ch = \'\\\\102\';\",\"D. ch = \'\\\\x42\';\"],\"answer\":\"A\",\"explanation\":\"本题考查数据类型与表达式。正确答案是 A。字符常量 B 需写成 \'B\'；66、八进制 102、十六进制 42 均为 \'B\' 的 ASCII 值。\",\"source\":\"夸克扫描王_该函数使用输出(6).jpeg\",\"id\":50,\"memoryAid\":\"字符B赋值要引号，ASCII码66也能用，八进制十六进制都算数\"},{\"type\":\"single\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-29\"],\"difficulty\":2,\"question\":\"以下程序运行后的输出结果是（ ）。\\n```c\\n#include \\\"stdio.h\\\"\\nint main(){\\n    char ch = \'a\';\\n    int x = 5;\\n    float s = 2.5F;\\n    printf(\\\"%d,%d,%d\\\\n\\\", sizeof(ch), sizeof(x), sizeof(s));\\n    return 0;\\n}\\n```\",\"options\":[\"A. 1,2,4\",\"B. 1,4,4\",\"C. 1,4,8\",\"D. a,5,2.5\"],\"answer\":\"B\",\"explanation\":\"本题考查数据类型与表达式。正确答案是 B。严格 C 中 sizeof 返回 size_t，printf 应用 %zu；教材按常见环境取 1,4,4。\",\"source\":\"夸克扫描王_该函数使用输出(6).jpeg\",\"id\":51,\"memoryAid\":\"sizeof测量字节数，char是一int是四，float也是四字节\"},{\"type\":\"single\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-30\"],\"difficulty\":1,\"question\":\"以下选项中，不正确的 C 语言浮点型常量是（ ）。\",\"options\":[\"A. 160.\",\"B. 0.12\",\"C. 2e4.2\",\"D. 0.0\"],\"answer\":\"C\",\"explanation\":\"本题考查数据类型与表达式。正确答案是 C。指数部分必须是整数。\",\"source\":\"夸克扫描王_该函数使用输出(7).jpeg\",\"id\":52,\"memoryAid\":\"浮点常量指数部分，必须是个整数值，2e4.2小数不合法\"},{\"type\":\"single\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-31\"],\"difficulty\":1,\"question\":\"以下选项中，（ ）是不正确的 C 语言字符型常量。\",\"options\":[\"A. \'a\'\",\"B. \'\\\\x41\'\",\"C. \'\\\\101\'\",\"D. \\\"a\\\"\"],\"answer\":\"D\",\"explanation\":\"本题考查数据类型与表达式。正确答案是 D。\\\"a\\\" 是字符串常量。\",\"source\":\"夸克扫描王_该函数使用输出(7).jpeg\",\"id\":53,\"memoryAid\":\"字符常量单引号，\\\"a\\\"双引是字符串，混用单双引就完蛋\"},{\"type\":\"single\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-32\"],\"difficulty\":1,\"question\":\"在 C 语言中，字符型数据在计算机内存中，以字符的（ ）形式存储。\",\"options\":[\"A. 原码\",\"B. 反码\",\"C. ASCII 码\",\"D. BCD 码\"],\"answer\":\"C\",\"explanation\":\"本题考查数据类型与表达式。正确答案是 C。教材口径为 ASCII；实际执行字符集由实现决定。\",\"source\":\"夸克扫描王_该函数使用输出(7).jpeg\",\"id\":54,\"memoryAid\":\"字符存储用ASCII，不是原码反码BCD，编码方式要记清\"},{\"type\":\"single\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-33\"],\"difficulty\":1,\"question\":\"若 x、i、j 和 k 都是 int 型变量，则计算下面表达式后，x 的值是（ ）。x = (i = 4, j = 16, k = 32)\",\"options\":[\"A. 4\",\"B. 16\",\"C. 32\",\"D. 52\"],\"answer\":\"C\",\"explanation\":\"本题考查数据类型与表达式。正确答案是 C。逗号表达式的值为最后一个表达式的值。\",\"source\":\"夸克扫描王_该函数使用输出(7).jpeg\",\"id\":55,\"memoryAid\":\"逗号表达式取最后，i=4,j=16,k=32，x的值就是32\"},{\"type\":\"single\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-34\"],\"difficulty\":1,\"question\":\"算术运算符、赋值运算符和关系运算符的运算优先级按从高到低依次为（ ）。\",\"options\":[\"A. 算术运算、赋值运算、关系运算\",\"B. 算术运算、关系运算、赋值运算\",\"C. 关系运算、赋值运算、算术运算\",\"D. 关系运算、算术运算、赋值运算\"],\"answer\":\"B\",\"explanation\":\"本题考查数据类型与表达式。正确答案是 B。\",\"source\":\"夸克扫描王_该函数使用输出(7).jpeg\",\"id\":56,\"memoryAid\":\"优先级从高到低排，算术关系再赋值，算关赋顺序不能乱\"},{\"type\":\"single\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-35\"],\"difficulty\":1,\"question\":\"若有代数式 3ae/bc，则不正确的 C 语言表达式是（ ）。\",\"options\":[\"A. a/b/c*e*3\",\"B. 3*a*e/b/c\",\"C. 3*a*e/b*c\",\"D. a*e/c/b*3\"],\"answer\":\"C\",\"explanation\":\"本题考查数据类型与表达式。正确答案是 C。按代数式理解为 3*a*e/(b*c)，C 等价于 (3*a*e/b)*c。\",\"source\":\"夸克扫描王_该函数使用输出(7).jpeg\",\"id\":57,\"memoryAid\":\"代数式三ae除bc，连除顺序要当心，先除b再除c才对，C选项把c乘上了\"},{\"type\":\"single\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-36\"],\"difficulty\":1,\"question\":\"表达式 !x || a == b 等效于（ ）。\",\"options\":[\"A. !((x||a)==b)\",\"B. !(x||y)==b\",\"C. !(x||(a==b))\",\"D. (!x)||(a==b)\"],\"answer\":\"D\",\"explanation\":\"本题考查数据类型与表达式。正确答案是 D。! 优先于 ==，== 优先于 ||。B 选项疑似扫描/印刷为 y。\",\"source\":\"夸克扫描王_该函数使用输出(7).jpeg\",\"id\":58,\"memoryAid\":\"逻辑运算优先级，!最高==其次，||最低括号来帮忙，!x||a==b等效D\"},{\"type\":\"single\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-37\"],\"difficulty\":1,\"question\":\"设整型变量 m,n,a,b,c,d 均为 1，执行 (m = a > b) && (n = c > d) 后，m,n 的值是（ ）。\",\"options\":[\"A. 0,0\",\"B. 0,1\",\"C. 1,0\",\"D. 1,1\"],\"answer\":\"B\",\"explanation\":\"本题考查数据类型与表达式。正确答案是 B。a>b 即 1>1 为假（0），m=0。由于 && 短路求值，左侧为假时右侧 (n=c>d) 不执行，n 保持原值 1。最终 m=0, n=1。\",\"source\":\"夸克扫描王_该函数使用输出(7).jpeg\",\"id\":59,\"memoryAid\":\"短路求值&&妙，左边为假右边跳，m赋值n不动，结果就是零和一\"},{\"type\":\"single\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-38\"],\"difficulty\":3,\"question\":\"设有语句 int a = 3;，则执行语句 a += a -= a *= a; 后，变量 a 的值是（ ）。\",\"options\":[\"A. 3\",\"B. 0\",\"C. 9\",\"D. -12\"],\"answer\":\"B\",\"explanation\":\"本题考查数据类型与表达式。正确答案是 B。按教材右结合计算：a*=a 后 a=9，a-=9 后 a=0，a+=0 后 a=0。注意：严格 C 标准中，同一表达式内多次修改同一变量属于未定义行为。\",\"source\":\"夸克扫描王_该函数使用输出(7).jpeg\",\"id\":60,\"memoryAid\":\"复合赋值右结合，先算a乘a得九，再算a减九得零，最后加零还是零\"},{\"type\":\"single\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-39\"],\"difficulty\":1,\"question\":\"在以下一组运算符中，优先级最低的运算符是（ ）。\",\"options\":[\"A. *\",\"B. !=\",\"C. +\",\"D. =\"],\"answer\":\"D\",\"explanation\":\"本题考查数据类型与表达式。正确答案是 D。赋值运算符优先级低于关系/相等/算术运算符。\",\"source\":\"夸克扫描王_该函数使用输出(7).jpeg\",\"id\":61,\"memoryAid\":\"赋值运算优先级最低，乘法不等加法高，等于号排最后头\"},{\"type\":\"single\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-40\"],\"difficulty\":3,\"question\":\"设整型变量 i 值为 2，表达式 (++i) + (++i) + (++i) 的结果是（ ）。\",\"options\":[\"A. 6\",\"B. 13\",\"C. 15\",\"D. 表达式出错\"],\"answer\":\"B\",\"explanation\":\"本题考查数据类型与表达式。正确答案是 B。\",\"source\":\"夸克扫描王_该函数使用输出(7).jpeg\",\"id\":62,\"memoryAid\":\"13\"},{\"type\":\"single\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-41\"],\"difficulty\":1,\"question\":\"若已定义 x 和 y 为 double 类型，则表达式 x = 1, y = x + 3/2 的值是（ ）。\",\"options\":[\"A. 1\",\"B. 2\",\"C. 2.0\",\"D. 2.5\"],\"answer\":\"C\",\"explanation\":\"本题考查数据类型与表达式。正确答案是 C。3/2 为整数除法得 1，逗号表达式值为 y 的值 2.0。\",\"source\":\"夸克扫描王_该函数使用输出(7).jpeg\",\"id\":63,\"memoryAid\":\"整数除法不带小数，三除二得一不是1.5，逗号表达式结果2.0\"},{\"type\":\"single\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-42\"],\"difficulty\":1,\"question\":\"sizeof(double) 的结果值是（ ）。\",\"options\":[\"A. 8\",\"B. 4\",\"C. 2\",\"D. 出错\"],\"answer\":\"A\",\"explanation\":\"本题考查数据类型与表达式。正确答案是 A。C 标准规定大小由实现决定；常见环境为 8。\",\"source\":\"夸克扫描王_该函数使用输出(7).jpeg\",\"id\":64,\"memoryAid\":\"double占八字节，sizeof结果就是八，浮点精度它最大\"},{\"type\":\"single\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-43\"],\"difficulty\":1,\"question\":\"设 a = 1, b = 2, c = 3, d = 4，则表达式 a < b ? a : c < d ? a : d 的结果为（ ）。\",\"options\":[\"A. 4\",\"B. 3\",\"C. 2\",\"D. 1\"],\"answer\":\"D\",\"explanation\":\"本题考查数据类型与表达式。正确答案是 D。a < b 为真，结果为 a，即 1。\",\"source\":\"夸克扫描王_该函数使用输出(7).jpeg\",\"id\":65,\"memoryAid\":\"三元运算从右往左，a<b为真取a，结果就是一\"},{\"type\":\"single\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-44\"],\"difficulty\":1,\"question\":\"设 a 为整型变量，不能正确表达数学关系 10 < a < 15 的 C 语言表达式是（ ）。\",\"options\":[\"A. 10 < a < 15\",\"B. a == 11 || a == 12 || a == 13 || a == 14\",\"C. a > 10 && a < 15\",\"D. !(a <= 10) && !(a >= 15)\"],\"answer\":\"A\",\"explanation\":\"本题考查数据类型与表达式。正确答案是 A。C 中不能用数学连写比较。\",\"source\":\"夸克扫描王_该函数使用输出(7).jpeg\",\"id\":66,\"memoryAid\":\"连写比较在C中不行，10<a<15要拆开，用&&连接两个判\"},{\"type\":\"single\",\"category\":\"数据类型与表达式\",\"tags\":[\"图片识别\",\"习题2-46\"],\"difficulty\":1,\"question\":\"表达式 18/4 * sqrt(4.0) / 8 值的数据类型是（ ）。\",\"options\":[\"A. int\",\"B. float\",\"C. double\",\"D. 不确定\"],\"answer\":\"C\",\"explanation\":\"本题考查数据类型与表达式。正确答案是 C。sqrt 返回 double，参与运算后结果为 double。\",\"source\":\"夸克扫描王_该函数使用输出(7).jpeg\",\"id\":67,\"memoryAid\":\"sqrt返回double型，参与运算结果也是它，整除乘sqrt类型不变\"},{\"type\":\"essay\",\"category\":\"编程练习\",\"tags\":[\"图片识别\",\"习题2-编程题1\"],\"difficulty\":1,\"question\":\"已知长方形的长和宽分别为 x 和 y，计算其周长和面积。\",\"options\":[],\"answer\":\"\",\"explanation\":\"本题为开放编程题，答案不唯一。解题时先明确输入、处理和输出三步，再选择合适的数据类型、分支/循环或数组实现。\",\"source\":\"夸克扫描王_该函数使用输出(8).jpeg\",\"id\":68,\"memoryAid\":\"长方形周长二倍长加宽，面积长乘宽记心间\"},{\"type\":\"essay\",\"category\":\"编程练习\",\"tags\":[\"图片识别\",\"习题2-编程题2\"],\"difficulty\":1,\"question\":\"编写一个程序，其功能为：从键盘上输入两个整型数据，分别存放在整型变量 a 和 b 中，输出表达式 a/b 和 a%b 的值。\",\"options\":[],\"answer\":\"\",\"explanation\":\"本题为开放编程题，答案不唯一。解题时先明确输入、处理和输出三步，再选择合适的数据类型、分支/循环或数组实现。\",\"source\":\"夸克扫描王_该函数使用输出(8).jpeg\",\"id\":69,\"memoryAid\":\"整数相除用斜杠，取余百分不能忘\"},{\"type\":\"essay\",\"category\":\"编程练习\",\"tags\":[\"图片识别\",\"习题2-编程题3\"],\"difficulty\":1,\"question\":\"编写一个程序，其功能为：从键盘上输入一个浮点数，然后分别输出该数的整数部分和小数部分。\",\"options\":[],\"answer\":\"\",\"e